WITH latest_match AS (SELECT s.id, s.supplier_name, s.country, s.city, latest.launch_date FROM suppliers s LEFT JOIN LATERAL (SELECT c.launch_date FROM products c WHERE c.supplier_id = s.id ORDER BY c.launch_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, supplier_name, city, CASE WHEN city RLIKE '^(New York|Tokyo)$' THEN 'OTHER_ZONE' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS city_zone FROM latest_match ORDER BY city_zone, city;
